CREATE TEMP TABLE old_bi AS SELECT document_id AS vid, badge_id FROM public.business_document_badges WHERE created_at < '2026-08-23 03:21:28.512634+00';
CREATE TEMP TABLE want_bi AS SELECT DISTINCT o.vid, r.tgt FROM old_bi o JOIN brules r ON r.src = o.badge_id;
DELETE FROM public.business_document_badges n WHERE n.created_at = '2026-08-23 03:21:28.512634+00' AND NOT EXISTS (SELECT 1 FROM want_bi w WHERE w.vid = n.document_id AND w.tgt = n.badge_id);
INSERT INTO public.business_document_badges (document_id, badge_id) SELECT w.vid, w.tgt FROM want_bi w WHERE NOT EXISTS (SELECT 1 FROM public.business_document_badges x WHERE x.document_id = w.vid AND x.badge_id = w.tgt);
CREATE TEMP TABLE old_gv AS SELECT generic_video_id AS vid, badge_id FROM public.generic_video_badges WHERE created_at < '2026-08-23 03:21:28.512634+00';
CREATE TEMP TABLE want_gv AS SELECT DISTINCT o.vid, r.tgt FROM old_gv o JOIN brules r ON r.src = o.badge_id;
DELETE FROM public.generic_video_badges n WHERE n.created_at = '2026-08-23 03:21:28.512634+00' AND NOT EXISTS (SELECT 1 FROM want_gv w WHERE w.vid = n.generic_video_id AND w.tgt = n.badge_id);
INSERT INTO public.generic_video_badges (generic_video_id, badge_id) SELECT w.vid, w.tgt FROM want_gv w WHERE NOT EXISTS (SELECT 1 FROM public.generic_video_badges x WHERE x.generic_video_id = w.vid AND x.badge_id = w.tgt);